SELECT * FROM node_cooperation_cancel_record WHERE is_del = 0
AND (organ_name LIKE CONCAT('%', #{keyword}, '%') OR organ_id LIKE CONCAT('%', #{keyword}, '%'))
AND cancel_date >= #{startTime}
AND cancel_date <= CONCAT(#{endTime}, ' 23:59:59')
ORDER BY cancel_date DESC
LIMIT #{offset}, #{pageSize}
